import{_ as e,a,o as r,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Attribute","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/attribute/index.md","filePath":"api/graphql-api/shop/attribute/index.md","lastUpdated":1786429091000}'),i={name:"api/graphql-api/shop/attribute/index.md"};function s(n,t,d,h,l,u){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="attribute" tabindex="-1">Attribute <a class="header-anchor" href="#attribute" aria-label="Permalink to &quot;Attribute&quot;">​</a></h1><p>The Attribute menu exposes the product attributes the store uses — things like colour, size, brand — and their options. A client uses it to build filter controls on a product-listing page and to render attribute-driven selectors (for example, the colour / size pickers on a configurable product).</p><h2 id="choosing-a-query" tabindex="-1">Choosing a query <a class="header-anchor" href="#choosing-a-query" aria-label="Permalink to &quot;Choosing a query&quot;">​</a></h2><p>Three queries read the same data at different scopes:</p><ul><li><strong>One attribute</strong> — <code>attribute(id:)</code> returns a single attribute together with its own options, in order. This is what a colour or size picker needs.</li><li><strong>Every attribute</strong> — <code>attributes</code> pages through the whole catalog. It takes no filter argument, so narrow the result in the client.</li><li><strong>Every option</strong> — <code>attributeOptions</code> pages through option values across all attributes at once. Nodes carry no attribute reference, so it suits building a lookup table rather than filling one control.</li></ul><p>For a category&#39;s filter sidebar, none of these is the right tool — <a href="/api/graphql-api/shop/queries/get-category-attribute-filters.html">Category Attribute Filters</a> returns only the attributes marked filterable for that category, with the price range attached.</p><h2 id="reading-the-values" tabindex="-1">Reading the values <a class="header-anchor" href="#reading-the-values" aria-label="Permalink to &quot;Reading the values&quot;">​</a></h2><p>Two things catch clients out across all three queries. The boolean-looking fields — <code>isFilterable</code>, <code>isConfigurable</code>, <code>valuePerLocale</code> and the rest — are the <strong>strings</strong> <code>&quot;1&quot;</code> and <code>&quot;0&quot;</code>, so a truthiness test on <code>&quot;0&quot;</code> gives the wrong answer. And <code>adminName</code> is an internal label that is never translated; the shopper-facing text is <code>translation.name</code> on an attribute and <code>translation.label</code> on an option.</p><p>When filtering products, the key is the attribute&#39;s <code>code</code> and the value is the option&#39;s <code>_id</code>.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List attributes</td><td><a href="/api/graphql-api/shop/queries/get-attributes.html"><code>attributes</code></a></td><td>Cursor-paginated list of every attribute, each with its options and translations.</td></tr><tr><td>View one attribute</td><td><a href="/api/graphql-api/shop/queries/get-attribute.html"><code>attribute</code></a></td><td>A single attribute by IRI or numeric ID, with its own options.</td></tr><tr><td>List attribute options</td><td><a href="/api/graphql-api/shop/queries/get-attribute-options.html"><code>attributeOptions</code></a></td><td>Option values across every attribute, unscoped.</td></tr></tbody></table><p>These are public read endpoints — they require the storefront key header but no customer Bearer token. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',12)]))}const b=e(i,[["render",s]]);export{p as __pageData,b as default};
